"""Run the workspace's command the way the task's interface describes."""

import json
import os
import subprocess
import sys

COMMAND = "fare"
PATH = os.path.join(os.environ["WARRANT_WORKSPACE"], COMMAND)


def call(request=None, raw=None, timeout=10):
    """Send a request (or raw text) on stdin. Returns (exit status, parsed JSON output or None)."""
    if not os.access(PATH, os.X_OK):
        sys.exit(f"the workspace has no executable named fare")
    text = raw if raw is not None else json.dumps(request)
    try:
        done = subprocess.run([PATH], input=text, capture_output=True, text=True, timeout=timeout)
    except subprocess.TimeoutExpired:
        return 124, None
    output = done.stdout.strip()
    if not output:
        return done.returncode, None
    try:
        return done.returncode, json.loads(output)
    except json.JSONDecodeError:
        return done.returncode, output


def finish(problems, summary):
    if problems:
        shown = problems if len(problems) <= 12 else problems[:10] + [f"...and {len(problems) - 10} more"]
        print("\n".join(shown))
        sys.exit(1)
    print(summary)

"""P1: `fare` follows the interface in C3."""

from _cmd import call, finish

FIELDS = {"fares_cents", "total_cents"}
REQUESTS = [
    {"age": 30, "trips": [{"board_minute": 600, "from_zone": 1, "to_zone": 2}]},
    {"age": 8, "trips": [{"board_minute": 420, "from_zone": 2, "to_zone": 2}, {"board_minute": 900, "from_zone": 2, "to_zone": 4}]},
    {"age": 70, "trips": []},
]
problems = []

for request in REQUESTS:
    status, body = call(request)
    if status != 0:
        problems.append(f"{request}: exited with status {status}, expected 0")
    elif not isinstance(body, dict) or set(body) != FIELDS:
        problems.append(f"{request}: expected an object with exactly {sorted(FIELDS)}, got {body!r}")
    elif not isinstance(body["fares_cents"], list) or len(body["fares_cents"]) != len(request["trips"]):
        problems.append(f"{request}: fares_cents must list one fare per trip, got {body['fares_cents']!r}")
    elif not all(type(fare) is int for fare in body["fares_cents"]) or type(body["total_cents"]) is not int:
        problems.append(f"{request}: every amount must be a whole number of cents, got {body!r}")
    elif body["total_cents"] != sum(body["fares_cents"]):
        problems.append(f"{request}: total_cents must be the sum of fares_cents, got {body!r}")

refused = {"age": 30, "trips": [{"board_minute": 600, "from_zone": 1, "to_zone": 7}]}
status, body = call(refused)
if status != 2 or body is not None:
    problems.append(f"a zone of 7 must be refused with status 2 and no output, got status {status} and {body!r}")

finish(problems, "contract ok: 4 requests")

"""P2: the example days written in the intent."""

from _cmd import call, finish


def trip(minute, start, end):
    return {"board_minute": minute, "from_zone": start, "to_zone": end}


SCENARIOS = [
    ("S1", {"age": 40, "trips": [trip(450, 2, 5), trip(490, 5, 6), trip(600, 6, 6)]}, [555, 0, 270], 825),
    ("S2", {"age": 11, "trips": [trip(480, 1, 3), trip(1000, 3, 3)]}, [230, 135], 365),
    ("S3", {"age": 30, "trips": [trip(420, 1, 6), trip(480, 6, 4), trip(720, 4, 6), trip(1080, 6, 6)]}, [745, 0, 355, 0], 1100),
]
problems = []
for scenario, request, fares, total in SCENARIOS:
    status, body = call(request)
    expected = {"fares_cents": fares, "total_cents": total}
    if status != 0 or body != expected:
        problems.append(f"{scenario}: expected {expected}, got {body!r} (status {status})")

finish(problems, "scenarios ok: S1, S2, S3")

