#!/usr/bin/env python3
import sys, json

def main():
    try:
        data = json.loads(sys.stdin.read())
    except Exception:
        sys.exit(2)
    if not isinstance(data, dict):
        sys.exit(2)
    # extract fields
    age = data.get("age")
    trips = data.get("trips")
    if age is None or trips is None:
        sys.exit(2)
    if not isinstance(age, int):
        sys.exit(2)
    if age < 0 or age > 120:
        sys.exit(2)
    if not isinstance(trips, list):
        sys.exit(2)
    # Validate each trip
    prev_minute = -1
    for trip in trips:
        if not isinstance(trip, dict):
            sys.exit(2)
        bm = trip.get("board_minute")
        fz = trip.get("from_zone")
        tz = trip.get("to_zone")
        if bm is None or fz is None or tz is None:
            sys.exit(2)
        if not isinstance(bm, int) or not isinstance(fz, int) or not isinstance(tz, int):
            sys.exit(2)
        if bm < 0 or bm > 1439:
            sys.exit(2)
        if fz < 1 or fz > 6 or tz < 1 or tz > 6:
            sys.exit(2)
        if bm < prev_minute:
            sys.exit(2)
        prev_minute = bm
    # compute fares
    cap_dict = { "adult": 1100, "child": 550, "senior": 440 }
    if age < 5:
        fare_type = "free"  # 0
    elif 5 <= age <= 15:
        fare_type = "child"
    elif 65 <= age <= 120:
        fare_type = "senior"
    else:
        fare_type = "adult"
    # Determine adult fare calculation
    # For each trip, compute adult fare: base 270 + 95*abs(fz - tz)
    adult_fares = []
    for trip in trips:
        fz = trip["from_zone"]
        tz = trip["to_zone"]
        adult_fare = 270 + 95 * abs(fz - tz)
        adult_fares.append(adult_fare)
    # Determine final fares per trip
    fares_cents = []
    # Transfer window
    window_start = None
    running_total = 0
    cap = cap_dict[fare_type]
    for idx, trip in enumerate(trips):
        # Determine if transfer
        if window_start is None:
            # first trip always pays
            transfer = False
        else:
            if trip["board_minute"] <= window_start + 90:
                transfer = True
            else:
                transfer = False
        if transfer:
            fare = 0
        else:
            # compute fare according to age
            if fare_type == "free":
                fare = 0
            elif fare_type == "adult":
                fare = adult_fares[idx]
            elif fare_type == "child":
                # half of adult fare, rounded down to multiple of 5
                base = adult_fares[idx] * 50 // 100
                fare = (base // 5) * 5
            else:  # senior
                base = adult_fares[idx] * 40 // 100
                fare = (base // 5) * 5
        # apply cap
        if running_total >= cap:
            # Already at cap, fare stays 0
            fare = 0
        else:
            if running_total + fare > cap:
                fare = cap - running_total
        fares_cents.append(fare)
        running_total += fare
        # If not transfer, open new window
        if not transfer:
            window_start = trip["board_minute"]
    total_cents = sum(fares_cents)
    # Output JSON
    out = {"fares_cents": fares_cents, "total_cents": total_cents}
    sys.stdout.write(json.dumps(out, separators=(",", ":")))
    sys.exit(0)

if __name__ == "__main__":
    main()
